    /**
     * Dispay field in metabox
     * @param array $field Field data
     * @param object $post Post object
     * @return void
     */
    public function display_meta_box_field($field = array(), $post)
    {

        if (!is_array($field) || 0 == count($field)) return;

        $field = '<p class="form-field"><label for="' . esc_attr($field['id']) . '">' . esc_html($field['label']) . '</label>' .
            $this->display_field($field, $post, false) . '</p>' . "\n";

        echo wp_kses($field, self::$allowed_html);;
    }

    /**
     * Save metabox fields
     * @param integer $post_id Post ID
     * @return void
     */
    public function save_meta_boxes($post_id = 0)
    {

        if (!$post_id) return;

        $post_type = get_post_type($post_id);

        $fields = apply_filters($post_type . '_custom_fields', array(), $post_type);

        if (!is_array($fields) || 0 == count($fields)) return;

        foreach ($fields as $field) {
            $request_id = sanitize_text_field($_REQUEST[$field['id']]);
            if (isset($request_id) && $request_id) {
                update_post_meta($post_id, $field['id'], $this->validate_field($request_id, $field['type']));
            } else {
                update_post_meta($post_id, $field['id'], '');
            }
        }
    }

}

